import{_ as t,o as l,c as n,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Keynote: Town Hall - Panel","description":"","frontmatter":{"title":"Keynote: Town Hall - Panel","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph社区","分布式存储","Ceph开发","Ceph性能","Ceph功能"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Keynote_-_Town_Hall_-_Panel.md","filePath":"posts/2019/Keynote_-_Town_Hall_-_Panel.md","lastUpdated":1780459816000}'),p={name:"posts/2019/Keynote_-_Town_Hall_-_Panel.md"};function s(a,e,r,_,i,C){return l(),n("div",null,[...e[0]||(e[0]=[o("<p>本次会议为Ceph社区的线上会议，于2023年11月举行。会议主要围绕Ceph社区的现状、发展计划、问题解答等主题展开。</p><p><strong>会议主要内容</strong>：</p><ul><li><strong>会议开场</strong>： 主持人介绍了参会人员，并欢迎提问。每位参会人员进行了自我介绍，包括姓名、工作内容和常用的编辑器。</li><li><strong>如何开始贡献</strong>： 讨论了新用户如何开始为Ceph贡献代码，建议从回溯工作开始，熟悉软件的代码库，并鼓励参与文档贡献。</li><li><strong>文档贡献</strong>： 讨论了Ceph文档的更新和维护，指出文档信息架构需要更新，鼓励大家通过GitHub链接直接修复文档中的错误。</li><li><strong>Ceph功能与性能</strong>： 讨论了Ceph的深度去重功能、不同客户端的性能差异、读取所有副本的OSD的性能问题、Ceph与OpenStack Cinder和OpenStack Swift的集成等。</li><li><strong>Ceph社区协作</strong>： 讨论了Ceph社区的协作方式，提到使用IRC、邮件列表和GitHub进行沟通。</li><li><strong>Ceph发展路线图</strong>： 讨论了Ceph的发展路线图，可以通过Ceph Tracker和Trello板跟踪Ceph的开发进度。</li><li><strong>会议总结</strong>： 感谢参会人员的提问和贡献，鼓励大家继续关注Ceph社区，并积极参与贡献。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Ceph社区将继续改进入门页面和文档。</li><li>鼓励更多用户参与Ceph文档的贡献。</li><li>Ceph社区将继续关注性能和功能改进。</li><li>Ceph社区将继续加强协作，共同推动Ceph的发展。</li></ul>",5)])])}const d=t(p,[["render",s]]);export{g as __pageData,d as default};
